// BED artik DB'de (data_operation_recipes.pipeline_id); Claim sorgusu bed_file olarak donduruyor.
// Claim returns [{success:true}] when 0 rows claimed -> drop it so worker stops cleanly
const items = $("Claim All Pending").all().filter(it => it.json.read_ref != null);
return items.map((item, idx) => ({
  json: { ...item.json, bed_file_path: item.json.bed_file || "" },
  pairedItem: { item: idx }
}));

