const metrics = JSON.parse($input.item.json.stdout);
const data_op_ref = metrics.data_op_ref;

// data_op_ref hariç tüm parametreleri al
const excludeKeys = ['data_op_ref'];
const result = [];

for (const [key, value] of Object.entries(metrics)) {
  if (excludeKeys.includes(key)) continue;
  // Hesaplanamayan metrikler (null / NA / boş) ölçüm olarak yazılmaz —
  // measurement_reads.value_as_number NOT NULL.
  if (value === null || value === undefined || value === 'NA' || value === '') continue;
  if (typeof value === 'number' && Number.isNaN(value)) continue;
  result.push({
    data_op_ref: data_op_ref,
    parameter: key,
    value: value
  });
}

return result.map(item => ({ json: item }));

const self = $execution.id;
const data = ($input.first().json.data) || [];
const others = data.filter(e => String(e.id) !== String(self));
return [{ json: { otherRunning: others.length, otherIds: others.map(e => e.id) } }];

